import json, re
data = json.load(open('batches/batch_0011.json'))

def japanese_count(s):
    return len(re.findall(r'[぀-ヿ一-鿿]', s or ''))

def best_decode(s):
    if not s:
        return s
    candidates = []
    try:
        b = s.encode('latin1')
    except Exception:
        return s
    for enc in ('utf-8','shift_jis','cp932','euc_jp'):
        try:
            cand = b.decode(enc, errors='ignore')
            candidates.append((japanese_count(cand), cand))
        except Exception:
            pass
    candidates.append((japanese_count(s), s))
    candidates.sort(key=lambda x: -x[0])
    return candidates[0][1]

out = {}
for d in data:
    fixed = dict(d)
