import json
data = json.load(open('batches/batch_0011.json'))

def best_decode(s):
    if not s:
        return s
    try:
        b = s.encode('latin1')
    except Exception:
        return s
    try:
        return b.decode('utf-8')
    except UnicodeDecodeError as e:
        if e.start >= len(b) - 4:
            # likely truncation cut a multibyte char at the very end
            return b.decode('utf-8', errors='ignore')
        # not utf-8 at all -> try shift_jis / cp932
        for enc in ('cp932','shift_jis','euc_jp'):
            try:
                return b.decode(enc)
            except Exception:
                continue
        return b.decode('utf-8', errors='replace')

out = {}
for d in data:
    fixed = dict(d)
    fixed['_fixed_title'] = best_decode(d.get('title',''))
    fixed['_fixed_desc'] = best_decode(d.get('desc',''))
    fixed['_fixed_body'] = best_decode(d.get('body',''))
    out[str(d['idx'])] = fixed

